"use client";
import React, { useMemo, useState, useEffect, useCallback } from "react";
// import Chart from "react-apexcharts";
import { ApexOptions } from "apexcharts";
import ChartTab, { type TimeFilter } from "../common/ChartTab";
import dynamic from "next/dynamic";
import { COLORS } from "@/shared/constants/colors";
import type { ShipmentOverTime } from "@/lib/api/dashboard";
import { dashboardApi } from "@/lib/api/dashboard";
import Skeleton from "../ui/skeleton/Skeleton";

// Dynamically import the ReactApexChart component
const ReactApexChart = dynamic(() => import("react-apexcharts"), {
  ssr: false,
});

interface StatisticsChartProps {
  shipmentsOverTime: ShipmentOverTime[];
}

const StatisticsChart = React.memo(({ shipmentsOverTime: initialData }: StatisticsChartProps) => {
  const [shipmentsOverTime, setShipmentsOverTime] = useState<ShipmentOverTime[]>(initialData);
  const [selectedFilter, setSelectedFilter] = useState<TimeFilter>("30");
  const [loading, setLoading] = useState(false);

  const fetchData = useCallback(async (days: number) => {
    try {
      setLoading(true);
      const data = await dashboardApi.getShipmentsOverTime(days);
      setShipmentsOverTime(data);
    } catch (error) {
      console.error("Error fetching shipments over time:", error);
    } finally {
      setLoading(false);
    }
  }, []);

  const handleFilterChange = useCallback((filter: TimeFilter) => {
    setSelectedFilter(filter);
    const days = parseInt(filter);
    fetchData(days);
  }, [fetchData]);

  // Update local state when initial data changes
  useEffect(() => {
    setShipmentsOverTime(initialData);
  }, [initialData]);
  const options: ApexOptions = useMemo(() => ({
    legend: {
      show: false, // Hide legend
      position: "top",
      horizontalAlign: "left",
    },
    colors: [COLORS.PRIMARY, COLORS.BRAND[200]], // Define line colors
    chart: {
      fontFamily: "Outfit, sans-serif",
      height: 310,
      type: "line", // Set the chart type to 'line'
      toolbar: {
        show: false, // Hide chart toolbar
      },
    },
    stroke: {
      curve: "straight", // Define the line style (straight, smooth, or step)
      width: [2, 2], // Line width for each dataset
    },

    fill: {
      type: "gradient",
      gradient: {
        opacityFrom: 0.55,
        opacityTo: 0,
      },
    },
    markers: {
      size: 0, // Size of the marker points
      strokeColors: "#fff", // Marker border color
      strokeWidth: 2,
      hover: {
        size: 6, // Marker size on hover
      },
    },
    grid: {
      xaxis: {
        lines: {
          show: false, // Hide grid lines on x-axis
        },
      },
      yaxis: {
        lines: {
          show: true, // Show grid lines on y-axis
        },
      },
    },
    dataLabels: {
      enabled: false, // Disable data labels
    },
    tooltip: {
      enabled: true, // Enable tooltip
      x: {
        format: "dd MMM yyyy", // Format for x-axis tooltip
      },
    },
    xaxis: {
      type: "category", // Category-based x-axis
      categories: shipmentsOverTime.map((item) => {
        const date = new Date(item.date);
        return date.toLocaleDateString("en-US", { month: "short", day: "numeric" });
      }),
      axisBorder: {
        show: false, // Hide x-axis border
      },
      axisTicks: {
        show: false, // Hide x-axis ticks
      },
      tooltip: {
        enabled: false, // Disable tooltip for x-axis points
      },
    },
    yaxis: {
      labels: {
        style: {
          fontSize: "12px", // Adjust font size for y-axis labels
          colors: ["#6B7280"], // Color of the labels
        },
      },
      title: {
        text: "", // Remove y-axis title
        style: {
          fontSize: "0px",
        },
      },
    },
  }), [shipmentsOverTime]);

  const series = useMemo(() => [
    {
      name: "Total",
      data: shipmentsOverTime.map((item) => item.total),
    },
    {
      name: "Completed",
      data: shipmentsOverTime.map((item) => item.completed),
    },
  ], [shipmentsOverTime]);

  return (
    <div className="rounded-2xl border border-gray-200 bg-white px-5 pb-5 pt-5 dark:border-gray-800 dark:bg-white/3 sm:px-6 sm:pt-6">
      <div className="flex flex-col gap-5 mb-6 sm:flex-row sm:items-center sm:justify-between">
        <div>
          <h3 className="text-lg font-semibold text-gray-800 dark:text-white/90">
            Shipment Statistics
          </h3>
          <p className="mt-1 text-gray-500 text-theme-sm dark:text-gray-400">
            Shipment trends over time
          </p>
        </div>
        <div className="flex items-center justify-end">
          <ChartTab selected={selectedFilter} onChange={handleFilterChange} />
        </div>
      </div>

      {loading ? (
        <div className="max-w-full overflow-x-auto custom-scrollbar">
          <div className="min-w-[1000px] xl:min-w-full">
            <Skeleton variant="rectangular" height={310} width="100%" className="rounded-lg" />
          </div>
        </div>
      ) : (
        <div className="max-w-full overflow-x-auto custom-scrollbar">
          <div className="min-w-[1000px] xl:min-w-full">
            <ReactApexChart
              options={options}
              series={series}
              type="area"
              height={310}
            />
          </div>
        </div>
      )}
    </div>
  );
});

StatisticsChart.displayName = "StatisticsChart";

export default StatisticsChart;
